(() => {
  "use strict";

  const normalisePath = (value) => {
    const path = String(value || "/").replace(/\/index\.html$/i, "/");
    return path.length > 1 ? path.replace(/\/$/, "") : path;
  };

  const refreshActiveNavigation = () => {
    const currentPath = normalisePath(window.location.pathname);
    const currentHash = window.location.hash || "";
    const cards = Array.from(document.querySelectorAll(".nav-card-menu a.nav-menu-card"));
    const primaryLinks = Array.from(document.querySelectorAll(".nav-links > li > a"));

    primaryLinks.forEach((link) => {
      let url;
      try { url = new URL(link.href, window.location.href); } catch (error) { return; }
      const active = normalisePath(url.pathname) === currentPath && (url.hash || "") === currentHash;
      link.classList.toggle("active", active);
      if (active) link.setAttribute("aria-current", "page");
      else link.removeAttribute("aria-current");
    });

    document.querySelectorAll(".nav-dropdown-toggle.active").forEach((toggle) => toggle.classList.remove("active"));
    cards.forEach((link) => {
      let url;
      try { url = new URL(link.href, window.location.href); } catch (error) { return; }
      const samePath = normalisePath(url.pathname) === currentPath;
      const exactHash = (url.hash || "") === currentHash;
      const active = samePath && exactHash;
      link.classList.toggle("active", active);
      if (active) link.setAttribute("aria-current", "page");
      else link.removeAttribute("aria-current");

      if (samePath) {
        link.closest(".nav-dropdown")?.querySelector(":scope > .nav-dropdown-toggle")?.classList.add("active");
      }
    });
  };

  const preparePremiumReveals = () => {
    const targets = Array.from(document.querySelectorAll([
      ".start-here-mini-card",
      ".home-editorial-card",
      ".latest-update-row",
      ".digital-tool-row",
      ".premium-discovery-panel",
      ".premium-site-footer .footer-main > *",
      ".premium-site-footer .footer-community-strip"
    ].join(",")));

    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reducedMotion || !("IntersectionObserver" in window)) {
      targets.forEach((target) => target.classList.add("premium-reveal", "is-visible"));
      return;
    }

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        entry.target.classList.add("is-visible");
        observer.unobserve(entry.target);
      });
    }, { threshold: 0.1, rootMargin: "0px 0px -34px" });

    targets.forEach((target, index) => {
      target.classList.add("premium-reveal");
      target.style.setProperty("--premium-reveal-delay", `${Math.min((index % 4) * 70, 210)}ms`);
      observer.observe(target);
    });
  };

  document.addEventListener("DOMContentLoaded", () => {
    refreshActiveNavigation();
    preparePremiumReveals();
  });
  window.addEventListener("hashchange", refreshActiveNavigation);
})();

;
(() => {
  "use strict";

  const NEW_TARGETS = [
    ".eyebrow",
    ".home-editorial-meta > span",
    ".home-editorial-image > span",
    ".latest-update-meta b",
    ".latest-new-badge",
    ".inspiration-link-row small",
    ".new-label",
    ".question-tag"
  ].join(",");

  const wrapNewWord = (root = document) => {
    const targets = [];
    if (root.nodeType === Node.ELEMENT_NODE && root.matches?.(NEW_TARGETS)) targets.push(root);
    root.querySelectorAll?.(NEW_TARGETS).forEach((element) => targets.push(element));

    targets.forEach((element) => {
      if (element.querySelector(".new-blink")) return;
      const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT);
      let textNode;
      while ((textNode = walker.nextNode())) {
        const match = textNode.nodeValue.match(/\bNew\b/i);
        if (!match) continue;
        const value = textNode.nodeValue;
        const index = match.index;
        const fragment = document.createDocumentFragment();
        fragment.append(value.slice(0, index));
        const blink = document.createElement("span");
        blink.className = "new-blink";
        blink.textContent = value.slice(index, index + match[0].length);
        fragment.append(blink, value.slice(index + match[0].length));
        textNode.replaceWith(fragment);
        break;
      }
    });
  };

  const prepareNewPanels = () => {
    const panels = Array.from(document.querySelectorAll(".premium-discovery-panel"));
    if (!panels.length) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduced || !("IntersectionObserver" in window)) {
      panels.forEach((panel) => panel.classList.add("premium-reveal", "is-visible"));
      return;
    }

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        entry.target.classList.add("is-visible");
        observer.unobserve(entry.target);
      });
    }, { threshold: 0.12, rootMargin: "0px 0px -28px" });

    panels.forEach((panel, index) => {
      panel.classList.add("premium-reveal");
      panel.style.setProperty("--premium-reveal-delay", `${index * 90}ms`);
      observer.observe(panel);
    });
  };

  document.addEventListener("DOMContentLoaded", () => {
    wrapNewWord();
    prepareNewPanels();

    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => mutation.addedNodes.forEach((node) => {
        if (node.nodeType === Node.ELEMENT_NODE) wrapNewWord(node);
      }));
    });
    observer.observe(document.body, { childList: true, subtree: true });
  });
})();

;
(() => {
  "use strict";

  const SELECTORS = {
    practiceMain: ".typing-page, .shortcut-page, .quiz-page",
    practiceApp: ".typing-app-card, .shortcut-app-card, .quiz-app-card"
  };

  function enhanceNewArticleBadge(root = document) {
    const badges = [];
    if (root.nodeType === Node.ELEMENT_NODE && root.matches?.(".home-editorial-image > span")) badges.push(root);
    root.querySelectorAll?.(".home-editorial-image > span").forEach((item) => badges.push(item));
    badges.forEach((badge) => {
      if (badge.classList.contains("home-editorial-badge")) return;
      badge.classList.add("home-editorial-badge");
      badge.setAttribute("aria-label", "New article");
      badge.innerHTML = '<span class="new-blink">NEW</span><span>ARTICLE</span>';
    });
  }

  function structureDigitalToolsMenu() {
    document.querySelectorAll("#digital-tools-menu").forEach((menu) => {
      const items = Array.from(menu.children).filter((item) => item.tagName === "LI" && !item.classList.contains("nav-tools-group-label"));
      if (!items.length) return;

      items[0].classList.add("nav-tools-overview");
      if (!menu.querySelector(".nav-tools-group-label")) {
        const label = document.createElement("li");
        label.className = "nav-tools-group-label";
        label.setAttribute("aria-hidden", "true");
        label.textContent = "Tool Categories";
        items[0].insertAdjacentElement("afterend", label);
      }

      items.slice(1).forEach((item) => item.classList.add("nav-tools-category"));
      menu.setAttribute("data-hierarchy-ready", "true");
    });
  }

  function focusIcon() {
    return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 3H4a1 1 0 0 0-1 1v4M16 3h4a1 1 0 0 1 1 1v4M8 21H4a1 1 0 0 1-1-1v-4M16 21h4a1 1 0 0 0 1-1v-4"/></svg>';
  }

  function initPracticeFocusMode() {
    const main = document.querySelector(SELECTORS.practiceMain);
    if (!main || main.querySelector(".tool-focus-toolbar")) return;
    const app = main.querySelector(SELECTORS.practiceApp);
    if (!app) return;

    document.body.classList.add("tool-practice-page");

    const toolbar = document.createElement("div");
    toolbar.className = "tool-focus-toolbar";
    toolbar.innerHTML = `
      <div class="tool-focus-intro">
        <span aria-hidden="true">◎</span>
        <div><strong>Practice Workspace</strong><small>Use Focus Mode to remove distractions and fit more practice on screen.</small></div>
      </div>
      <div class="tool-focus-actions">
        <button class="tool-focus-button" type="button" aria-pressed="false"><span>Focus Mode</span><b aria-hidden="true">→</b></button>
        <button class="tool-fullscreen-button" type="button" aria-label="Open browser full screen" title="Open browser full screen">${focusIcon()}</button>
      </div>
      <span class="tool-focus-status" role="status" aria-live="polite"></span>`;
    main.insertBefore(toolbar, app);

    const focusButton = toolbar.querySelector(".tool-focus-button");
    const focusLabel = focusButton.querySelector("span");
    const focusArrow = focusButton.querySelector("b");
    const fullscreenButton = toolbar.querySelector(".tool-fullscreen-button");
    const status = toolbar.querySelector(".tool-focus-status");
    let previousScroll = 0;

    const setFocusMode = (enabled, { announce = true } = {}) => {
      if (enabled === document.body.classList.contains("tool-focus-mode")) return;
      if (enabled) previousScroll = window.scrollY;
      document.body.classList.toggle("tool-focus-mode", enabled);
      document.documentElement.classList.toggle("tool-focus-mode", enabled);
      focusButton.setAttribute("aria-pressed", String(enabled));
      focusLabel.textContent = enabled ? "Exit Focus Mode" : "Focus Mode";
      focusArrow.textContent = enabled ? "×" : "→";
      if (announce) status.textContent = enabled ? "Focus Mode opened. Navigation and extra panels are hidden." : "Focus Mode closed. Full page navigation restored.";
      if (enabled) {
        requestAnimationFrame(() => {
          main.scrollTop = 0;
          focusButton.focus({ preventScroll: true });
        });
      } else {
        requestAnimationFrame(() => window.scrollTo({ top: previousScroll, behavior: "smooth" }));
      }
    };

    focusButton.addEventListener("click", () => setFocusMode(!document.body.classList.contains("tool-focus-mode")));

    fullscreenButton.addEventListener("click", async () => {
      try {
        if (!document.fullscreenElement) {
          await document.documentElement.requestFullscreen();
          status.textContent = "Browser full screen opened. Press Escape to leave full screen.";
        } else {
          await document.exitFullscreen();
        }
      } catch (error) {
        status.textContent = "Browser full screen is not available here. Focus Mode still works normally.";
      }
    });

    document.addEventListener("fullscreenchange", () => {
      const active = Boolean(document.fullscreenElement);
      fullscreenButton.setAttribute("aria-label", active ? "Exit browser full screen" : "Open browser full screen");
      fullscreenButton.title = active ? "Exit browser full screen" : "Open browser full screen";
      fullscreenButton.classList.toggle("is-active", active);
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && document.body.classList.contains("tool-focus-mode") && !document.fullscreenElement) {
        setFocusMode(false);
      }
    });
  }

  function boot() {
    enhanceNewArticleBadge();
    structureDigitalToolsMenu();
    initPracticeFocusMode();

    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        mutation.addedNodes.forEach((node) => {
          if (node.nodeType !== Node.ELEMENT_NODE) return;
          enhanceNewArticleBadge(node);
          if (node.matches?.("#digital-tools-menu") || node.querySelector?.("#digital-tools-menu")) structureDigitalToolsMenu();
        });
      });
    });
    observer.observe(document.body, { childList: true, subtree: true });
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot, { once: true });
  else boot();
})();

;
(() => {
  "use strict";

  const qs = (selector, root = document) => root.querySelector(selector);
  const qsa = (selector, root = document) => Array.from(root.querySelectorAll(selector));

  function initQrJourney() {
    const nav = qs(".qr-step-nav");
    const buttons = qsa(".qr-step-button", nav || document);
    if (!nav || !buttons.length || nav.querySelector(".qr-step-progress-summary")) return;

    const title = qs(".qr-step-nav-title", nav);
    const summary = document.createElement("div");
    summary.className = "qr-step-progress-summary";
    summary.setAttribute("aria-live", "polite");
    summary.innerHTML = `
      <div class="qr-step-progress-copy"><span data-qr-progress-copy>Step 1 of ${buttons.length}</span><strong data-qr-progress-percent>${Math.round(100 / buttons.length)}% complete</strong></div>
      <div class="qr-step-progress-track" aria-hidden="true"><span data-qr-progress-bar></span></div>`;
    title?.insertAdjacentElement("afterend", summary);

    const mobile = document.createElement("div");
    mobile.className = "qr-mobile-journey";
    mobile.innerHTML = `
      <button type="button" data-qr-mobile-prev aria-label="Previous QR Builder step">‹</button>
      <div class="qr-mobile-current">
        <div class="qr-mobile-current-line"><strong data-qr-mobile-title>QR Type</strong><span data-qr-mobile-copy>Step 1 of ${buttons.length}</span></div>
        <div class="qr-mobile-progress" aria-hidden="true"><span data-qr-mobile-bar></span></div>
      </div>
      <button type="button" data-qr-mobile-next aria-label="Next QR Builder step">›</button>`;
    nav.appendChild(mobile);

    const update = () => {
      let index = buttons.findIndex((button) => button.classList.contains("is-active"));
      if (index < 0) index = 0;
      const current = buttons[index];
      const percent = Math.round(((index + 1) / buttons.length) * 100);
      const label = `Step ${index + 1} of ${buttons.length}`;
      const currentTitle = qs("strong", current)?.textContent.trim() || `Step ${index + 1}`;

      const copy = qs("[data-qr-progress-copy]", summary);
      const pct = qs("[data-qr-progress-percent]", summary);
      const bar = qs("[data-qr-progress-bar]", summary);
      if (copy) copy.textContent = label;
      if (pct) pct.textContent = `${percent}% complete`;
      if (bar) bar.style.width = `${percent}%`;

      const mobileTitle = qs("[data-qr-mobile-title]", mobile);
      const mobileCopy = qs("[data-qr-mobile-copy]", mobile);
      const mobileBar = qs("[data-qr-mobile-bar]", mobile);
      const prev = qs("[data-qr-mobile-prev]", mobile);
      const next = qs("[data-qr-mobile-next]", mobile);
      if (mobileTitle) mobileTitle.textContent = currentTitle;
      if (mobileCopy) mobileCopy.textContent = label;
      if (mobileBar) mobileBar.style.width = `${percent}%`;
      if (prev) prev.disabled = index === 0;
      if (next) next.disabled = index === buttons.length - 1;

      buttons.forEach((button, buttonIndex) => {
        button.setAttribute("aria-label", `${buttonIndex + 1}. ${qs("strong", button)?.textContent.trim() || "QR Builder step"}${button.classList.contains("is-complete") ? ", completed" : ""}${buttonIndex === index ? ", current step" : ""}`);
      });
    };

    qs("[data-qr-mobile-prev]", mobile)?.addEventListener("click", () => {
      const index = buttons.findIndex((button) => button.classList.contains("is-active"));
      buttons[Math.max(0, index - 1)]?.click();
    });
    qs("[data-qr-mobile-next]", mobile)?.addEventListener("click", () => {
      const index = buttons.findIndex((button) => button.classList.contains("is-active"));
      buttons[Math.min(buttons.length - 1, index + 1)]?.click();
    });

    const observer = new MutationObserver(update);
    buttons.forEach((button) => observer.observe(button, { attributes: true, attributeFilter: ["class", "aria-current"] }));
    update();
  }

  function initQrValidation() {
    const errors = qsa(".qr-inline-error");
    if (!errors.length) return;

    const sync = (error) => {
      const visible = !error.hidden && Boolean(error.textContent.trim());
      const field = error.closest(".qr-field");
      field?.classList.toggle("has-error", visible);
      const input = field?.querySelector("input,select,textarea,[role='combobox']");
      if (visible) {
        error.setAttribute("role", "alert");
        input?.setAttribute("aria-invalid", "true");
      } else if (input?.getAttribute("aria-invalid") === "true") {
        input.setAttribute("aria-invalid", "false");
      }
    };

    errors.forEach((error) => {
      new MutationObserver(() => sync(error)).observe(error, {
        attributes: true,
        attributeFilter: ["hidden"],
        childList: true,
        characterData: true,
        subtree: true
      });
      sync(error);
    });
  }

  function initShortcutFeedback() {
    const feedback = qs("#shortcutFeedback");
    if (!feedback) return;
    feedback.setAttribute("role", "status");
    feedback.setAttribute("aria-live", "polite");

    const sync = () => {
      feedback.classList.toggle("is-visible", Boolean(feedback.textContent.trim()));
      qsa(".shortcut-choice-btn", feedback.closest(".shortcut-app-card") || document).forEach((button) => {
        if (button.classList.contains("correct-answer")) button.setAttribute("aria-label", `${button.textContent.trim()}, correct answer`);
        else if (button.classList.contains("wrong-answer")) button.setAttribute("aria-label", `${button.textContent.trim()}, your incorrect answer`);
      });
    };
    new MutationObserver(sync).observe(feedback.closest(".shortcut-question-card") || feedback, {
      attributes: true,
      childList: true,
      subtree: true,
      attributeFilter: ["class"]
    });
    sync();
  }

  function auditInvalidFields() {
    qsa("[aria-invalid='true']").forEach((field) => field.closest(".qr-field,.form-group,.field-group")?.classList.add("has-error"));
  }

  function boot() {
    initQrJourney();
    initQrValidation();
    initShortcutFeedback();
    auditInvalidFields();
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot, { once: true });
  else boot();
})();

;
(function () {
  "use strict";

  const currentPath = (window.location.pathname || "").toLowerCase();
  const compactToolPattern = /(?:^|\/)(?:typing-trainer|shortcut-trainer|quiz|calculator|qr-code-generator)\.html$/;
  const focusedDigitalToolPattern = /\/digital-tools\/(?:typing-trainer|shortcut-keys-trainer|ict-quiz|scientific-calculator|qr-code-generator)\.html$/;

  if (compactToolPattern.test(currentPath) || focusedDigitalToolPattern.test(currentPath)) return;

  const navbar = document.querySelector(".navbar");
  if (!navbar || navbar.querySelector(".ai-live-strip")) return;

  const messages = [
    "One skill today can open a door tomorrow.",
    "Keep learning—your progress is building something powerful.",
    "Learn. Believe. Grow. Build."
  ];

  const strip = document.createElement("div");
  strip.className = "ai-live-strip";
  strip.setAttribute("role", "group");
  strip.setAttribute("aria-live", "off");
  strip.setAttribute("aria-label", "Local date, time, and encouragement");
  strip.innerHTML = `
    <div class="ai-live-primary">
      <span class="ai-live-icon" aria-hidden="true">🌙</span>
      <strong class="ai-live-greeting">Good evening</strong>
      <span class="ai-live-separator" aria-hidden="true">·</span>
      <span class="ai-live-date-full"></span>
      <span class="ai-live-date-short"></span>
      <span class="ai-live-separator" aria-hidden="true">·</span>
      <time class="ai-live-clock"></time>
    </div>
    <div class="ai-live-encouragement" aria-hidden="true"><span></span></div>
  `;

  navbar.appendChild(strip);
  navbar.classList.add("has-live-strip");

  const icon = strip.querySelector(".ai-live-icon");
  const greeting = strip.querySelector(".ai-live-greeting");
  const fullDate = strip.querySelector(".ai-live-date-full");
  const shortDate = strip.querySelector(".ai-live-date-short");
  const clock = strip.querySelector(".ai-live-clock");
  const encouragement = strip.querySelector(".ai-live-encouragement");
  const encouragementText = encouragement.querySelector("span");

  const fullDateFormatter = new Intl.DateTimeFormat("en-GB", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric"
  });

  const shortDateFormatter = new Intl.DateTimeFormat("en-GB", {
    day: "numeric",
    month: "short"
  });

  const timeFormatter = new Intl.DateTimeFormat("en-US", {
    hour: "numeric",
    minute: "2-digit",
    second: "2-digit",
    hour12: true
  });

  function timeIdentity(hour) {
    if (hour >= 5 && hour < 12) return { icon: "🌅", greeting: "Good morning" };
    if (hour >= 12 && hour < 18) return { icon: "☀️", greeting: "Good afternoon" };
    if (hour >= 18 && hour < 21) return { icon: "🌇", greeting: "Good evening" };
    return { icon: "🌙", greeting: "Good evening" };
  }

  function updateClock() {
    const now = new Date();
    const identity = timeIdentity(now.getHours());

    icon.textContent = identity.icon;
    greeting.textContent = identity.greeting;
    fullDate.textContent = fullDateFormatter.format(now);
    shortDate.textContent = shortDateFormatter.format(now);
    clock.dateTime = now.toISOString();
    clock.textContent = timeFormatter.format(now);
  }

  let messageIndex = 0;
  encouragementText.textContent = messages[messageIndex];

  function rotateMessage() {
    encouragement.classList.add("is-changing");
    window.setTimeout(function () {
      messageIndex = (messageIndex + 1) % messages.length;
      encouragementText.textContent = messages[messageIndex];
      encouragement.classList.remove("is-changing");
    }, 330);
  }

  function updateScrolledState() {
    navbar.classList.toggle("nav-scrolled", window.scrollY > 42);
  }

  const menuToggle = navbar.querySelector(".menu-toggle");
  if (menuToggle) {
    const syncMenuState = function () {
      navbar.classList.toggle("live-menu-open", menuToggle.checked);
    };
    menuToggle.addEventListener("change", syncMenuState);
    syncMenuState();
  }

  updateClock();
  updateScrolledState();
  window.setInterval(updateClock, 1000);
  window.setInterval(rotateMessage, 13000);
  window.addEventListener("scroll", updateScrolledState, { passive: true });
})();
